from django.db import migrations, models
from django.utils import timezone


def rellenar_folios(apps, schema_editor):
    Reporte = apps.get_model("reportes", "Reporte")
    anio = timezone.localdate().year
    prefijo = f"AR-{anio}-"
    secuencia = 0
    for reporte in Reporte.objects.filter(folio__isnull=True).order_by(
        "creado_en", "id"
    ):
        secuencia += 1
        folio = f"{prefijo}{secuencia:06d}"
        while Reporte.objects.filter(folio=folio).exists():
            secuencia += 1
            folio = f"{prefijo}{secuencia:06d}"
        reporte.folio = folio
        reporte.save(update_fields=["folio"])


